// ===== Aiuti comuni del workflow 07 (blocco uguale in più nodi: si modifica nel generatore) =====
const CARTELLA_MIME = 'application/vnd.google-apps.folder';
const NOME_IN_LAVORAZIONE = '_in_lavorazione';
const NOME_LAVORATI = '_lavorati';
const NOME_PRONTI = 'Pronti';
const MAX_SLOT_CLIP = 16; // posti per le clip nei nodi dell'officina (8 + 8)
const MAX_BYTE_CLIP = 300 * 1024 * 1024;
const MAX_BYTE_TOTALE = 800 * 1024 * 1024;
const MARCHIO_NEUTRO = { colori: { primario: '#222222', secondario: '#F5F5F5', testo: '#FFFFFF' }, font: 'Roboto', logo: '' };
const ESTENSIONI_VIDEO = ['mp4', 'mov', 'm4v', 'avi', 'mkv', 'webm', 'mts', 'm2ts', '3gp', 'hevc', 'mpg', 'mpeg'];
const ESTENSIONI_AUDIO = ['mp3', 'm4a', 'wav', 'aac', 'ogg', 'oga', 'flac', 'opus'];

function testo(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function norm(v) { return testo(v).toLowerCase(); }
function senzaAccenti(s) { return String(s).normalize('NFD').replace(/[̀-ͯ]/g, ''); }
function siNo(v) { return ['si', 'sì', 'yes', 'true', '1', 'x', 'vero', 'attivo', 'ok'].includes(norm(v)); }
function intero(v, predefinito) { const n = parseInt(v, 10); return Number.isFinite(n) ? n : predefinito; }
function numero(v, predefinito) {
  if (v === null || v === undefined || v === '') return predefinito;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : predefinito;
}
function slug(v, max) {
  const s = senzaAccenti(norm(v)).replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, max || 24).replace(/-+$/g, '');
  return s || 'reel';
}
// Data e ora di Roma (anche col cambio dell'ora legale) senza librerie.
function partiRoma(d) {
  const f = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23', weekday: 'short' });
  const p = {};
  for (const x of f.formatToParts(d)) p[x.type] = x.value;
  const giorni = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return { data: p.year + '-' + p.month + '-' + p.day, ora: p.hour + ':' + p.minute, minutiGiorno: Number(p.hour) * 60 + Number(p.minute), giornoSettimana: giorni[p.weekday] };
}
function timbro() { const p = partiRoma(new Date()); return p.data.split('-').reverse().join('/') + ' ' + p.ora; }
function idDrive(v) {
  const s = testo(v);
  const m = s.match(/\/d\/([A-Za-z0-9_-]{10,})/) || s.match(/[?&]id=([A-Za-z0-9_-]{10,})/) || s.match(/\/folders\/([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(s)) return s;
  return '';
}
function linkDrive(id) { return 'https://drive.google.com/file/d/' + id + '/view'; }
// Testo sicuro per Telegram in modalità HTML (i messaggi normali).
function h(v) { return String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
// Testo sicuro per il Markdown di Telegram (il messaggio coi bottoni Approva/Rifiuta lo usa sempre).
function md(v) { return String(v === null || v === undefined ? '' : v).replace(/([_*`\[\\])/g, '\\$1'); }
function accorcia(s, n) { const t = String(s); return t.length > n ? t.slice(0, n - 1) + '…' : t; }
function unisciNota(prima, nuova) {
  const p = testo(prima);
  const n = testo(nuova);
  const tutto = p ? p + ' · ' + n : n;
  return tutto.length > 480 ? '…' + tutto.slice(-479) : tutto;
}
function estensione(nome) { const m = testo(nome).toLowerCase().match(/\.([a-z0-9]{1,5})$/); return m ? m[1] : ''; }
function eCartella(f) { return f && f.mimeType === CARTELLA_MIME; }
function eClip(f) { return !eCartella(f) && (/^video\//i.test(testo(f.mimeType)) || ESTENSIONI_VIDEO.includes(estensione(f.name))); }
function eMusica(f) { return !eCartella(f) && /^musica\.[a-z0-9]{1,5}$/i.test(testo(f.name)) && (/^audio\//i.test(testo(f.mimeType)) || ESTENSIONI_AUDIO.includes(estensione(f.name))); }
function eBrief(f) { return !eCartella(f) && norm(f.name) === 'brief.txt'; }
function eSrt(f) { return !eCartella(f) && norm(f.name) === 'sottotitoli.srt'; }
function byteDi(f) { const n = Number(f && f.size); return Number.isFinite(n) ? n : 0; }
