    finale.push({ type: 'text', name: 'Outro', track: 2, time: 0, text: testo(p.outro), x: '50%', y: '62%', width: '84%', x_alignment: '50%', y_alignment: '50%', font_family: p.font, font_weight: '800', font_size: '7 vmin', fill_color: c.testo });
    elementi.push({ type: 'composition', name: 'Finale', track: 1, duration: SECONDI_CARTELLO, fill_color: c.primario, elements: finale });
  }
