// Creatomate nelle JPG non uscirebbero. La copertina è senza battute, come quella dell'officina.
// Il reel si divide in 6 parti uguali: in ogni parte si prende l'istante più vicino al centro in cui si legge una
// battuta (un po' dentro i suoi bordi); se in quella parte nessuno parla si prende il centro (lì non c'è niente da leggere).
function istantiConBattute(D, battute) {
  const t = (x) => Math.max(0, Math.round(x * 100) / 100);
  const fineUtile = Math.max(0, D - 0.05);
  const out = [];
  for (let k = 0; k < 6; k++) {
    const a = D * k / 6;
    const z = D * (k + 1) / 6;
    const centro = (a + z) / 2;
    let scelta = { tempo: t(centro), battuta: '', distanza: Infinity };
    for (const b of battute) {
      const bi = Number(b.time);
      const bf = bi + Number(b.duration);
      const m = Math.min(0.15, (bf - bi) / 3);
      // centesimi verso l'interno della finestra (la piccola tolleranza evita che 4,85 diventi 4,84 per la virgola mobile)
      const lo = Math.ceil(Math.max(bi + m, a, 0) * 100 - 1e-6) / 100;
      const hi = Math.floor(Math.min(bf - m, z, fineUtile) * 100 + 1e-6) / 100;
      if (!(hi >= lo)) continue;
      const x = Math.min(Math.max(centro, lo), hi);
      const dist = Math.abs(x - centro);
      if (dist < scelta.distanza) scelta = { tempo: t(x), battuta: b.name, distanza: dist };
    }
    out.push({ tempo: scelta.tempo, battuta: scelta.battuta });
  }
  return out;
}
function istantanee(script, durata) {
