  const battute = (mont.elements || []).filter((e) => eBattuta(e) && Number.isFinite(Number(e.time)) && Number(e.duration) > 0);
  const voci = istantiConBattute(D, battute).map((x, k) => ({ ruolo: 'fotogramma', indice: k, tempo: x.tempo, battuta: x.battuta }));
  voci.push({ ruolo: 'copertina', indice: 6, tempo: t(D > 4 ? D * 0.25 : D / 2), battuta: '' });
  return voci.map((v) => {
    const s = JSON.parse(JSON.stringify(script));
    delete s.duration;
    delete s.frame_rate;
    s.output_format = 'jpg';
    s.snapshot_time = v.tempo;
    if (v.ruolo === 'copertina') for (const e of s.elements) if (e.name === 'Montaggio') e.elements = e.elements.filter((x) => !eBattuta(x));
