// pubblico qualsiasi, per esempio il sito del locale (si scarica con una richiesta HTTP).
function logoDi(v) {
  const s = testo(v);
  if (!s) return { tipo: 'nessuno', id: '', url: '' };
  const daDrive = /^https?:\/\/(drive|docs)\.google\.com\//i.test(s) || /^[A-Za-z0-9_-]{10,}$/.test(s);
  if (daDrive && idDrive(s)) return { tipo: 'drive', id: idDrive(s), url: '' };
  if (/^https:\/\/[^\s"'<>]+$/i.test(s)) return { tipo: 'url', id: '', url: s };
  return { tipo: 'sbagliato', id: '', url: '' };
}
function leggiMarchio(v) {
  const neutro = JSON.parse(JSON.stringify(MARCHIO_NEUTRO));
  const vuoto = (motivo) => ({ marchio: Object.assign(neutro, { font_testo: neutro.font, logo_tipo: 'nessuno', logo_url: '' }), valido: false, motivo });
  const s = testo(v);
  if (!s) return vuoto('vuoto');
  let m;
  try { m = JSON.parse(s); } catch (e) { return vuoto('non è un JSON scritto bene'); }
  if (!m || typeof m !== 'object' || Array.isArray(m)) return vuoto('non valido');
  const col = m.colori && typeof m.colori === 'object' ? m.colori : {};
  const problemi = [];
  const colori = {};
  for (const k of ['primario', 'secondario', 'testo']) {
    if (coloreValido(col[k])) colori[k] = testo(col[k]);
    else { colori[k] = neutro.colori[k]; problemi.push('colore ' + k); }
  }
  // «accento» è facoltativo: se è scritto male si ignora (le grafiche usano i tre colori principali)
  if (coloreValido(col.accento)) colori.accento = testo(col.accento);
  const font = testo(m.font);
  if (!font) problemi.push('font');
  const logo = logoDi(m.logo);
  if (logo.tipo === 'sbagliato') problemi.push('link del logo');
  return {
    marchio: { colori, font: font || neutro.font, font_testo: testo(m.font_testo) || font || neutro.font, logo: logo.id, logo_tipo: logo.tipo === 'sbagliato' ? 'nessuno' : logo.tipo, logo_url: logo.url },
    valido: problemi.length === 0, motivo: problemi.length ? 'incompleto (' + problemi.join(', ') + ')' : '',
  };
}
// I tre colori che l'officina conosce (il contratto non prevede «accento»).
function coloriOfficina(c) { return { primario: c.primario, secondario: c.secondario, testo: c.testo }; }
function piattaformeDi(c) {
  const ig = testo(c.ig_user_id);
  const fb = testo(c.fb_page_id);
  return ig && fb ? 'ig+fb' : ig ? 'ig' : fb ? 'fb' : '';
}
// Letture fatte con HTTP Request (le API rispondono sempre con un oggetto, anche quando non c'è niente):
// Sheets → { values: [[intestazioni], [riga], …] } ; Drive → { files: [ … ] } (una voce per pagina).
// Accetta anche voci già «a oggetti» (una riga o un file per voce).
function righeFoglio(items) {
  const out = [];
  for (const it of items || []) {
    const j = (it && it.json) || {};
    if (j.error) continue;
    if (Array.isArray(j.values)) {
      const nomi = (j.values[0] || []).map((x) => testo(x));
      j.values.slice(1).forEach((r, k) => {
        const o = { _riga: k + 2 };
        nomi.forEach((n, i) => { if (n) o[n] = r && r[i] !== undefined && r[i] !== null ? r[i] : ''; });
        if (nomi.some((n) => n && testo(o[n]))) out.push(o);
      });
    } else if (!('range' in j) && !('majorDimension' in j) && Object.keys(j).length) out.push(j);
  }
  return out;
}
function fileDaElenco(items) {
  const out = [];
  for (const it of items || []) {
    const j = (it && it.json) || {};
    if (j.error) continue;
    if (Array.isArray(j.files)) out.push(...j.files.filter((f) => f && f.id));
    else if (j.id) out.push(j);
  }
  return out;
}
// L'officina risponde con indirizzi completi: si tiene solo il percorso e si usa OFFICINA_URL del Config.
function urlOfficina(cfg, url) {
  const base = testo(cfg.OFFICINA_URL).replace(/\/+$/, '');
  const percorso = testo(url).replace(/^https?:\/\/[^\/]+/i, '').replace(/^\/+/, '');
  return percorso ? base + '/' + percorso : '';
}
function erroreDi(j) {
  if (!j) return '';
  const e = j.error;
  if (!e) return '';
  if (typeof e === 'string') return e;
  return testo(e.message || e.description || e.messaggio || JSON.stringify(e)).slice(0, 300);
}
// L'errore di una voce: nei nodi HTTP/Drive sta in json.error, nei nodi Google Sheets nella voce stessa (item.error).
function erroreVoce(it) {
  if (!it) return '';
  const e = erroreDi(it.json);
  if (e) return e;
  const x = it.error;
  if (!x) return '';
  return testo(typeof x === 'string' ? x : (x.message || x.description || JSON.stringify(x))).slice(0, 300);
}
