// Una richiesta per istantanea: se anche una sola non parte si ripiega sull'officina (che fa copertina e fotogrammi da sé).
const richieste = $('Istantanee da chiedere').all();
const voci = $input.all();
const out = [];
for (let k = 0; k < richieste.length; k++) {
  const v = (voci[k] || {}).json || {};
  const e = erroreDi(v);
  if (e || !testo(v.id) || norm(v.status) === 'failed') return [{ json: { stato: 'fallito', motivo: 'Creatomate non ha accettato le istantanee: ' + accorcia(e || testo(v.error_message) || 'numero del lavoro mancante', 160) } }];
  out.push({ json: { stato: 'attesa', render_id: testo(v.id), ruolo: richieste[k].json.ruolo, indice: richieste[k].json.indice } });
}
return out;

